public class CasterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("asString(\"hi\")", "hi", Caster.asString("hi"));
        check("asString(\"\")", "", Caster.asString(""));
        check("asString(42)", null, Caster.asString(42));
        check("asString(null)", null, Caster.asString(null));

        check("doubled(21)", 42, Caster.doubled(21));
        check("doubled(-3)", -6, Caster.doubled(-3));
        check("doubled(0)", 0, Caster.doubled(0));
        check("doubled(\"21\")", null, Caster.doubled("21"));
        check("doubled(null)", null, Caster.doubled(null));
        check("doubled(3.0) is null (Double is not Integer)", null, Caster.doubled(3.0));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

