public class Caster {

    public static String asString(Object o) {
        if (o instanceof String s) {
            return s;
        }
        return null;
    }

    public static Integer doubled(Object o) {
        if (o instanceof Integer i) {
            return i * 2;
        }
        return null;
    }
}
